public class RefactorDemo {

    // BEFORE — refactor this method
    public static void awardXp(String name, int level, int kills) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("Name required");
        }
        if (level < 1 || kills < 0) {
            throw new IllegalArgumentException("Invalid level/kills");
        }
        int xp = kills * 3;
        if (level > 5) xp += 50;
        if (xp > 100) xp = 100;
        System.out.println(name + " earned " + xp + " XP");
    }

    public static void main(String[] args) {
        awardXp("Lyria", 7, 8);
    }
}
